  "evt.wedding.label": "結婚式",
  "evt.wedding.tagline": "式、披露宴、衣装まで。表計算ソフトも気疲れもなし。",
  "evt.wedding.guests": "招待客の人数",
  "evt.wedding.tier.low": "少人数",
  "evt.wedding.tier.mid": "スタンダード",
  "evt.wedding.tier.high": "大規模",
  "evt.wedding.style.champetre.label": "🌾 ナチュラル・田園",
  "evt.wedding.style.champetre.tip": "土曜日を外し、6〜9月の繁忙期を避けるだけで会場費は20〜30%下がります。ケータリングの持ち込みを認める会場なら予算全体が変わります。地元の旬の花を選べば装花費はおよそ半分に。",
  "evt.wedding.style.urbain.label": "🏙️ アーバンシック",
  "evt.wedding.style.urbain.tip": "都市部では会場費とカメラマンに予算が集中します（首都圏ではこの2項目が30〜40%増）。レストランの一室を貸切にすれば、会場と料理を1つの見積もりにまとめられます。",
  "evt.wedding.style.traditionnel.label": "🎊 伝統・複数の儀式",
  "evt.wedding.style.traditionnel.tip": "宗教式・法律上の手続き・伝統儀式は、それぞれ別の予算です。最初に3つの枠を決め（結納金や式装束は独立した項目に）、両家の負担分は必ず書面で共有しましょう。",
  "evt.wedding.style.eco.label": "💚 かしこく少予算",
  "evt.wedding.style.eco.tip": "削っても後悔しにくい3項目は、招待状（デジタル化）、装飾（中古＋旬の花）、音楽（プレイリスト＋スピーカーのレンタル）。着席コースをビュッフェに変えると1人あたり約30%節約できます。",
  "evt.wedding.item.catering": "披露宴・料理（1人あたり）",
