  "evt.wedding.cheer.early": "予定より先行しています。これこそ落ち着いた結婚式の秘訣です。今積み立てた分だけ、当日に選べる選択肢が増えます。",
  "evt.wedding.cheer.onTrack": "順調です。資金づくりがスケジュールにきちんと追いついています。この調子なら、まさに「気疲れしない結婚式」になります。",
  "evt.wedding.cheer.behind": "資金づくりがスケジュールより少し遅れています。慌てずに、毎月の積立額を増やすか、どこか1項目を調整しましょう（装飾やペーパーアイテムは料理より削りやすい項目です）。",
  "evt.wedding.cheer.lastStretch": "いよいよ最終段階です。各業者に最終人数を確定して伝え（欠席者の分も食事代はかかります）、予備費には手をつけないでおきましょう。",
  "evt.travel.label": "旅行",
  "evt.travel.tagline": "移動・宿泊・現地費用。予想外の出費を防ぐ予算づくり。",
  "evt.travel.guests": "旅行する人数",
  "evt.travel.tier.low": "バックパック",
  "evt.travel.tier.mid": "標準",
  "evt.travel.tier.high": "奮発",
  "evt.travel.style.aventure.label": "🥾 格安アドベンチャー",
  "evt.travel.style.aventure.tip": "ホステル、ローカル列車、屋台の食事なら、移動費を除いて1日30〜40ユーロが目安。航空券は3〜4か月前に（平日発・第二空港利用で）押さえ、学校の長期休暇を外して出発しましょう。宿泊費はハイシーズンとオフで最大40%違います。",
  "evt.travel.style.detente.label": "🏖️ のんびり",
  "evt.travel.style.detente.tip": "リゾートやクラブ滞在なら、早めに予約したオールインクルーシブが個別払いより有利なことがほとんど。同じホテルを2〜3の予約サイトと公式サイトで比較し、価格をここに記録して推移を見ましょう。",
  "evt.travel.style.culture.label": "🏛️ 都市・文化めぐり",
  "evt.travel.style.culture.tip": "シティパス（美術館＋交通）は1日2か所回れば元が取れます。中心部より地下鉄沿線に泊まれば、移動15分の差で宿泊費が30%下がります。",
  "evt.travel.style.famille.label": "👨‍👩‍👧 家族で",
  "evt.travel.style.famille.tip": "4人以上ならキッチン付きアパートがホテルより有利です（外食費が一番膨らみます）。現地の子ども無料制度（交通・美術館）も確認を。12歳までが対象のことが多いです。",
  "evt.travel.item.transport": "往復の移動費（1人あたり）",
  "evt.travel.item.lodging": "宿泊費（滞在全体、1人あたり）",
