  "evt.party.style.enfant.tip": "自宅開催なら総額200ユーロ前後が目安。プロの司会・アニメーター（200〜300ユーロ）が費用の分かれ目です。5歳児なら、大人2人で仕切るゲームでも十分に盛り上がります。",
  "evt.party.style.adulte.label": "🥂 大人",
  "evt.party.style.adulte.tip": "立食スタイルなら着席ディナーの半額で済み、参加者も自然に交流できます。「1本持ち寄り」をお願いするのも、定番ながら効果的です。",
  "evt.party.style.surprise.label": "🎁 サプライズ",
  "evt.party.style.surprise.tip": "内緒の予算は、少額に分けて目立たないように。共有スペースではなく個人スペースでイベントを作れば、サプライズはサプライズのままです。",
