  "evt.religious.ms.dday": "行事の当日 ✨",
  "evt.religious.cheer.early": "数か月前から積み立てておくことが、行事前の値上がりに対する一番の備えです。相場が落ち着いているうちに買えます。",
  "evt.religious.cheer.onTrack": "専用の積立は順調です。素敵な行事を、借金なしで迎えられます。まさに理想的な形です。",
  "evt.religious.cheer.behind": "資金づくりが遅れています。後から返す借金をするより、少し控えめな祝い方を選びましょう。金額は誰も覚えていませんが、その時間はみんなが覚えています。",
  "evt.religious.cheer.lastStretch": "本番はもうすぐ。市場での最後の買い物は朝のほうが交渉しやすく、リストを紙に書いておけば余計な買い足しを防げます。",
