  "adv.be-succession-regions.action": "自分の地域のルールを確認する",
  "adv.be-succession-regions.body": "ベルギーでは相続税・贈与税は地域（州）の管轄です。フランドル・ワロン・ブリュッセルで税率も控除も異なり、基準になるのは相続人ではなく被相続人または贈与者の税務上の居住地です。動産・不動産の贈与など計画を立てる前に、必ず自分の地域のルールを確認しましょう。",
  "adv.be-succession-regions.title": "相続と贈与：すべては住む地域次第",
  "adv.ch-lamal-franchise.fig.1.value": "700 CHF/年",
  "adv.pets-budget-chat.body": "フード、猫砂、日常のケア（保険は別）で年600〜1 000 €、月あたり50〜85 €です。専用の費目に積み立てておけば、動物病院の出費が生活費を直撃しません。",
  "adv.pets-budget-chat.body.multi": "フード、猫砂、日常のケア（保険は別）で年600〜1 000 €、月あたり50〜85 €です。専用の費目に積み立てておけば、動物病院の出費が生活費を直撃しません。",
  "adv.pets-budget-chat.fig.0.label": "猫1匹の年間予算",
